// Worker entry for the Cloudflare copy: the OpenNext handler for every request, plus the daily Cron Trigger.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";

import { isPrivateContent, notFound } from "./lib/private-content";

type Env = { CRON_SECRET?: string };

export default {
  // Lesson files are read by the server through ASSETS only: a request from outside gets 404.
  fetch(req: Request, env: unknown, ctx: unknown) {
    if (isPrivateContent(new URL(req.url).pathname)) return notFound();
    return handler.fetch(req, env, ctx);
  },
  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    // Calls the daily route directly; the secret keeps it closed to the public.
    const req = new Request("https://internal/api/cron/daily", {
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
    });
    ctx.waitUntil(
      handler.fetch(req, env, ctx).then(async (res: Response) => {
        console.log(`cron daily: ${res.status} ${await res.text()}`);
      }),
    );
  },
};

// @ts-expect-error: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
